class AntennaChanged : public RefBase, public BnAntennaReceiver

----

AntennaManager& antenna_manager = AntennaManager::getInstance()

android::sp<IAntennaReceiver> receiver = new AntennaChanged();

antenna_manager.registerAntennaDTCReceiver(receiver);

class AudioReceiver : public BnAudioManagerReceiver

----

mAudioManager = AudioManager::instance();

mAudioReceiver = new AudioReceiver(*this);
mAudioManager->registerReceiver(0x1111, mAudioReceiver);

