class ConfigurationManagerReceiver : public BnConfigurationManagerReceiver

----

std::string ConfigDataList[] = { "RmtImmobi", "RmtConf",  . . . };

mConfigManager = ConfigManager::instance();

mConfigManagerReceiver = new ConfigurationManagerReceiver(*this);

for(auto name : ConfigDataList)
{

    mConfigManager->registerReceiver (configmgr::OEM_CONFIG_FILE, name.c_str(), mConfigManagerReceiver);

}

mECALLManager = ECALLManager::instance();

mECALLMgrReceiver = new ECALLReceiver(*this);

mECALLManager->registerReceiver(0x1111, mECALLMgrReceiver);

mFilesysManager = FilesysManager::instance();

mFilesysMgrReceiver = new FilesysReceiver(*this);
mFilesysManager->registerReceiver(0x1111, mFilesysMgrReceiver);

mPacketAudioManager = PacketAudioManager::instance();

mPacketAudioMgrReceiver = new PacketAudioReceiver(*this);

mPacketAudioManager->registerReceiver(0x1111, mPacketAudioMgrReceiver);

mProgManager  = ProgManager::instance();

mProgMgrReceiver = new ProgMgrReceiver(*this);
mProgManager ->attachReceiver(0x1111, mProgMgrReceiver);

